```svelte
<script>
	let text = $state('');

	const wordCount = $derived.by(() => {
		if (!text.trim()) return 0;
		return text.trim().split(/\s+/).length;
	});

	const charCount = $derived.by(() => text.length);

	const isLong = $derived.by(() => wordCount > 15);
</script>

<div>
	<input data-testid="text-input" type="text" bind:value={text} />
	<button data-testid="clear-button" on:click={() => text = ''}>Clear</button>
	<div>
		<p data-testid="word-count">Words: {wordCount}</p>
		<p data-testid="char-count">Characters: {charCount}</p>
		<p data-testid="length-indicator">Status: {isLong ? 'Long text' : 'Short text'}</p>
	</div>
</div>
