  let count = $state(5);
  let doubled = $state(10);

  $effect(() => {
    doubled = count * 2;
  });
</script>

<div>
  <p data-testid="number-value">Number: {count}</p>
  <p data-testid="doubled-value">Doubled: {doubled}</p>
  <button data-testid="increment-button" onclick={() => count += 1}>Increment</button>
</div>
